{
  "requirements": [
    {
      "target_id": "t0",
      "policy_source_id": "q12",
      "policy_quote": "- A payment plan can be created with `create_payment_plan` if the current balance is at least 100 USD and the account has no `broken_plan` within the last 6 months.",
      "requirement": "The `account_id` must belong to an account with a current balance of at least 100 USD (as per `get_billing` output)."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q12",
      "policy_quote": "- A payment plan can be created with `create_payment_plan` if the current balance is at least 100 USD and the account has no `broken_plan` within the last 6 months.",
      "requirement": "The `account_id` must have no `broken_plan` recorded in the last 6 months (as per `get_billing` output)."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q12",
      "policy_quote": "- The plan must have between 3 and 6 monthly installments, as chosen by the customer.",
      "requirement": "The `months` argument must be an integer between 3 and 6, inclusive, and must match the customer's confirmed choice."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q12",
      "policy_quote": "- The plan must have between 3 and 6 monthly installments, as chosen by the customer. The installment amount equals balance / months, rounded to the cent.",
      "requirement": "The `installment_usd` argument must equal the current balance (from `get_billing`) divided by the `months` value, rounded to the nearest cent."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q12",
      "policy_quote": "- Before `create_payment_plan`, present the details and get explicit confirmation (\"yes\"/\"да\") from the customer.",
      "requirement": "The customer must have explicitly confirmed the **latest** details of the payment plan (including `months` and `installment_usd`) in the conversation before the tool call."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q12",
      "policy_quote": "- You help residential customers with billing: balances, late fee waivers, payment plans and refunds of overpayments. You cannot change tariffs, meter readings or service addresses.",
      "requirement": "The `account_id` must belong to a **residential** account (i.e., it must **not** start with `com_`)."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q12",
      "policy_quote": "- You may add internal notes with `log_note` at any time; notes do not need confirmation.",
      "requirement": "No additional requirements apply to `log_note` calls, but they must not interfere with the current action's compliance."
    }
  ]
}

