    },
    {
      "target_id": "t0",
      "policy_source_id": "q18",
      "policy_quote": "You assist students with course registration for the current term: enrolling, joining waitlists and dropping sections. You cannot change grades, grant exceptions, or give academic advice beyond these rules.",
      "requirement": "The action must be limited to course registration (enrollment) and cannot include changing grades, granting exceptions, or providing academic advice beyond registration rules."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q18",
      "policy_quote": "If the student record shows any hold (financial, advising), no registration action is allowed until the hold is cleared; refer the student to the office that placed the hold.",
      "requirement": "No holds (financial, advising) must be present in the student record before enrollment."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q18",
      "policy_quote": "Verify the student with `verify_student` (student ID and PIN) before accessing records or acting. Act only for the verified student.",
      "requirement": "The student must be verified using the `verify_student` tool with the correct student ID and PIN before enrollment."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q18",
      "policy_quote": "The current time is 2025-08-20 14:00:00 CDT. The current term is Fall 2025.",
      "requirement": "The enrollment must occur during the current term (Fall 2025) and within the allowed time window for registration actions."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q18",
      "policy_quote": "You cannot do both [sending a message and making a tool call] at the same time.",
      "requirement": "The `enroll` tool call must be made without simultaneously sending a message to the user."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q18",
      "policy_quote": "Be truthful about the results of tool calls.",
      "requirement": "The enrollment must be based on accurate and truthful information from tool outputs."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q18",
      "policy_quote": "Financial aid, housing and tuition questions are out of scope: tell the student to contact the Bursar's office.",
      "requirement": "The enrollment action must not address financial aid, housing, or tuition questions."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q18",
      "policy_quote": "Do not guess course content, instructors or schedules beyond what tools return.",
      "requirement": "The enrollment must not rely on assumptions about course content, instructors, or schedules beyond the data provided by tool outputs."
    }
  ]
}

