{
  "requirements": [
    {
      "target_id": "t0",
      "policy_source_id": "q14",
      "policy_quote": "- A booking can be cancelled with `cancel_booking`. The cancellation fee depends on the time remaining until `pickup_time`:",
      "requirement": "The `fee_usd` must be **0 USD** if the time remaining until `pickup_time` is **48 hours or more** (calculated as `pickup_time` minus current time **2025-07-01 10:00:00 PDT**)."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q14",
      "policy_quote": "- Exception: customers with `tier` equal to `gold` never pay a cancellation fee (`fee_usd` = 0), regardless of timing.",
      "requirement": "The `fee_usd` must be **0 USD** if the customer's `tier` is **`gold`**, regardless of the time remaining until `pickup_time`."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q14",
      "policy_quote": "- The fee is charged automatically by the system to the booking's payment method; you must pass the correct `fee_usd`.",
      "requirement": "`fee_usd` must be a **non-negative integer** (either **0** or **50**) and must match the calculated fee based on the customer's tier and time until `pickup_time`."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q14",
      "policy_quote": "- Before any action that changes a booking (`cancel_booking`, ...), state the details and obtain explicit confirmation (\"yes\"/\"да\").",
      "requirement": "The assistant must **explicitly confirm the cancellation details** (booking ID, pickup time, and fee) with the user and receive confirmation **before** making the `cancel_booking` call."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q14",
      "policy_quote": "- You may only act on bookings listed in that customer's profile.",
      "requirement": "`booking_id` must belong to a booking **listed in the customer's profile** (retrieved via `get_customer`)."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q14",
      "policy_quote": "- You cannot create new bookings, change rental locations, or negotiate prices.",
      "requirement": "The `cancel_booking` action must **only cancel an existing booking** and cannot modify other booking attributes (e.g., location, price)."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q14",
      "policy_quote": "- You cannot do both [send a message and make a tool call] at the same time.",
      "requirement": "The `cancel_booking` call must be made **without** sending a message in the same turn."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q14",
      "policy_quote": "- Be truthful about tool results. If a tool returns an error, tell the customer.",
      "requirement": "If the `cancel_booking` call fails, the assistant must **inform the user** of the error."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q14",
      "policy_quote": "- You help customers of RoadWay Rentals manage existing bookings: cancellations, vehicle class changes, additional drivers and refunds.",
      "requirement": "The `cancel_booking` action must be **limited to managing existing bookings** (no other modifications allowed)."
    }
  ]
}

